import hmac
import hashlib
import base64
import json
import time
import os
import re
from urllib.parse import unquote

# Secure token signing key
SECRET_KEY = os.environ.get('JWT_SECRET', 'default-dev-key-change-in-prod')

def base64url_encode(data):
    return base64.urlsafe_b64encode(data).rstrip(b'=')

def base64url_decode(data):
    if isinstance(data, str):
        data = data.encode('ascii')
    # Add padding
    padding = 4 - len(data) % 4
    if padding != 4:
        data += b'=' * padding
    return base64.urlsafe_b64decode(data)

def create_token(payload, algorithm='HS256'):
    header = {'alg': algorithm, 'typ': 'JWT'}
    header_b64 = base64url_encode(json.dumps(header, separators=(',', ':')).encode())
    payload_b64 = base64url_encode(json.dumps(payload, separators=(',', ':')).encode())
    signing_input = header_b64 + b'.' + payload_b64
    signature = hmac.new(SECRET_KEY.encode(), signing_input, hashlib.sha256).digest()
    sig_b64 = base64url_encode(signature)
    return (signing_input + b'.' + sig_b64).decode()

def constant_time_compare(a, b):
    """Length-independent comparison to prevent timing attacks."""
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= x ^ y
    return result == 0

def verify_token(token):
    """Verify JWT token with algorithm restriction."""
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None

        header_b64, payload_b64, sig_b64 = parts

        # Decode and validate header
        header = json.loads(base64url_decode(header_b64))

        # Algorithm validation - only allow HS256
        allowed_algorithms = ['HS256']
        token_alg = header.get('alg', '')

        if token_alg not in allowed_algorithms:
            return None

        # Verify signature
        signing_input = (header_b64 + '.' + payload_b64).encode()
        expected_sig = hmac.new(SECRET_KEY.encode(), signing_input, hashlib.sha256).digest()
        actual_sig = base64url_decode(sig_b64)

        if not constant_time_compare(expected_sig, actual_sig):
            return None

        # Decode payload
        payload = json.loads(base64url_decode(payload_b64))

        # Check expiration
        if 'exp' in payload and payload['exp'] < time.time():
            return None

        return payload
    except Exception:
        return None

def normalize_path(path):
    """Normalize URL path to prevent traversal."""
    # URL decode
    decoded = unquote(path)
    # Remove double slashes
    while '//' in decoded:
        decoded = decoded.replace('//', '/')
    # Resolve relative components
    parts = decoded.split('/')
    normalized = []
    for part in parts:
        if part == '..':
            if normalized:
                normalized.pop()
        elif part != '.' and part != '':
            normalized.append(part)
    return '/' + '/'.join(normalized)

def check_admin_access(payload, resource_path):
    """Check if user has admin access to the requested resource."""
    role = payload.get('role', 'user')
    normalized = normalize_path(resource_path)

    # Admin panel access control
    if normalized.startswith('/admin'):
        if role == 'admin':
            return True
        return False
    return True

def handle_request(method, path, headers, body=None):
    """Main request handler with authentication."""
    # Extract token from Authorization header
    auth_header = headers.get('Authorization', '')

    if not auth_header.startswith('Bearer '):
        return {'status': 401, 'body': 'Missing authentication'}

    token = auth_header[7:]

    # Verify the token
    payload = verify_token(token)
    if payload is None:
        return {'status': 401, 'body': 'Invalid token'}

    # Check authorization for the path
    if not check_admin_access(payload, path):
        return {'status': 403, 'body': 'Forbidden'}

    # Route handling
    normalized = normalize_path(path)

    if normalized == '/admin/users' and method == 'GET':
        return {'status': 200, 'body': json.dumps(get_users())}
    elif normalized == '/admin/config' and method == 'GET':
        return {'status': 200, 'body': json.dumps(get_config())}
    elif normalized.startswith('/api/profile'):
        return {'status': 200, 'body': json.dumps({'user': payload.get('sub')})}
    else:
        return {'status': 404, 'body': 'Not found'}

def get_users():
    return [{'id': 1, 'name': 'admin'}, {'id': 2, 'name': 'user1'}]

def get_config():
    return {'debug': False, 'version': '1.2.3'}


# Request sanitization layer
class RequestSanitizer:
    """Sanitize incoming requests before processing."""

    BLOCKED_PATTERNS = [
        r'\.\.',
        r'%2e%2e',
        r'%252e',
    ]

    def __init__(self):
        self.compiled_patterns = [re.compile(p, re.IGNORECASE) for p in self.BLOCKED_PATTERNS]

    def sanitize_path(self, raw_path):
        """Check path for malicious patterns."""
        for pattern in self.compiled_patterns:
            if pattern.search(raw_path):
                return None
        return raw_path

    def sanitize_headers(self, headers):
        """Validate header values."""
        sanitized = {}
        for key, value in headers.items():
            # Prevent header injection
            if '\r' in value or '\n' in value:
                continue
            sanitized[key] = value
        return sanitized

    def process_request(self, method, path, headers, body=None):
        """Full request processing pipeline."""
        # Sanitize headers
        clean_headers = self.sanitize_headers(headers)

        # Sanitize path
        clean_path = self.sanitize_path(path)
        if clean_path is None:
            return {'status': 400, 'body': 'Invalid path'}

        return handle_request(method, clean_path, clean_headers, body)


# Entry point
sanitizer = RequestSanitizer()

def application(environ):
    """WSGI-like application entry point."""
    method = environ.get('REQUEST_METHOD', 'GET')
    path = environ.get('PATH_INFO', '/')
    headers = environ.get('HTTP_HEADERS', {})
    body = environ.get('BODY', None)

    return sanitizer.process_request(method, path, headers, body)
